def design(feats):
    X = np.asarray(feats.x, float); y = np.asarray(feats.y, float); n, p = X.shape
    ids = list(feats.ids)
    st = list(feats.stratum); lv = sorted(set(st))
    Z = np.ones((n, 1))
    if len(lv) > 1:
        Z = np.column_stack([Z] + [np.array([s == l for s in st], float) for l in lv[1:]])
    R = np.corrcoef(X, rowvar=False); R = np.nan_to_num(R)

    def col(j):
        return X[:, j[0]] * X[:, j[1]] if isinstance(j, tuple) else X[:, j]

    def ll(js):
        A = np.column_stack([Z] + [col(j) for j in js]) if js else Z
        b = np.zeros(A.shape[1])
        for _ in range(30):
            m = 1 / (1 + np.exp(-np.clip(A @ b, -30, 30)))
            w = m * (1 - m) + 1e-9
            H = A.T @ (A * w[:, None]) + 1e-6 * np.eye(A.shape[1])
            d = np.linalg.solve(H, A.T @ (y - m)); b += d
            if np.abs(d).max() < 1e-7: break
        m = np.clip(1 / (1 + np.exp(-np.clip(A @ b, -30, 30))), 1e-12, 1 - 1e-12)
        return float(np.sum(y * np.log(m) + (1 - y) * np.log(1 - m)))

    def gain(sel, j):
        return 2 * (ll(sel + [j]) - ll(sel))

    sel = []; base = ll([])
    for k in range(MAX_DRIVERS):
        alpha = 0.1 / p if k == 0 else 0.05 / p
        cand = [j for j in range(p) if all(abs(R[j, s]) < 0.6 for s in sel)]
        if not cand: break
        lls = {j: ll(sel + [j]) for j in cand}
        j = max(lls, key=lls.get)
        if stats.chi2.sf(2 * (lls[j] - ll(sel)), 1) > alpha: break
        clus = [c for c in cand if abs(R[j, c]) >= 0.6 and lls[c] >= lls[j] - 2]
        if len(clus) > 1:
            clus2 = [c for c in range(p) if abs(R[j, c]) >= 0.6 and c not in sel]
            j = min(clus, key=lambda c: sum(max(gain(sel + [c], o), 0) for o in clus2 if o != c))
        sel.append(j)
    changed = True
    while changed and sel:
        changed = False
        for j in list(sel):
            rest = [s for s in sel if s != j]
            if stats.chi2.sf(2 * (ll(sel) - ll(rest)), 1) > 0.01 / p:
                sel = rest; changed = True; break
    m = np.full(n, y.mean()); r = y - m
    pairs = [(a, c) for a in range(p) for c in range(a, p)]
    P = np.column_stack([X[:, a] * X[:, c] for a, c in pairs]); P = P - P.mean(0)
    sc = (r @ P) ** 2 / (m * (1 - m) @ (P ** 2) + 1e-9)
    res = []
    for t in np.argsort(-sc)[:20]:
        a, c = pairs[t]; mains = sorted(set(sel) | {a, c})
        g = 2 * (ll(mains + [(a, c)]) - ll(mains))
        if stats.chi2.sf(g, 1) < 0.005 / len(pairs): res.append((g, a, c))
    prods = []
    for g, a, c in sorted(res, reverse=True):
        if len(prods) < 2 and all(abs(R[a, x]) < 0.6 and abs(R[c, x]) < 0.6 for pr in prods for x in pr):
            prods.append((a, c))
    drivers = list(sel) + [x for pr in prods for x in dict.fromkeys(pr) if x not in sel]
    drivers = list(dict.fromkeys(drivers))[:MAX_DRIVERS]
    cols = sorted(set(drivers) | {x for pr in prods for x in pr})
    return Design(drivers=tuple(ids[j] for j in drivers), columns=tuple(ids[j] for j in cols),
                  products=tuple((ids[a], ids[c]) for a, c in prods), loadings={})

